import { registerWebComponents } from '@domg-wc/common';
import { VlSideSheet } from '@domg-wc/components/block';

registerWebComponents([VlSideSheet]);

import { registerWebComponents } from '@domg-wc/common';
import { VlButtonComponent } from '@domg-wc/components/atom';
import { VlSideSheet } from '@domg-wc/components/block';

registerWebComponents([VlSideSheet, VlButtonComponent]);

// De ids van de drie knoppen buiten de side-sheet staan niet in de story, die de click handlers rechtstreeks in de
// template bindt; ze dienen enkel om de knoppen hier terug te vinden.
customElements.whenDefined('vl-side-sheet').then(() => {
    const sideSheet = document.querySelector('#side-sheet-toggle');

    document.querySelector('#toggle-side-sheet').addEventListener('click', () => sideSheet.toggle());
    document.querySelector('#open-side-sheet').addEventListener('click', () => sideSheet.open());
    document.querySelector('#close-side-sheet').addEventListener('click', () => sideSheet.close());

    // Met --vl-side-sheet-width-mobile: 100% valt de toggle knop op mobiel buiten het scherm; deze knop in de
    // side-sheet sluit hem dan.
    document.querySelector('#vl-side-sheet-close-button').addEventListener('click', () => sideSheet.close());
});

